begin;
do $test$
declare
 a uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); shop_a uuid; shop_b uuid; orphan_shop uuid; system_shop uuid; r jsonb;
 p uuid; v uuid; before_audit bigint; rejected boolean; price bigint; catalog_count integer; svc uuid; barber uuid; slot timestamptz; day date; booking record; retry record; items jsonb; key uuid:=gen_random_uuid();
begin
 insert into auth.users(id,email,raw_user_meta_data) values(a,a||'@example.invalid','{}'),(b,b||'@example.invalid','{}');
 select count(*) into catalog_count from private.shop_catalog_references;
 if catalog_count<20 then raise exception 'FAIL incomplete real reference catalog'; end if;
 perform set_config('request.jwt.claim.sub',a::text,true);
 perform set_config('request.jwt.claim.role','authenticated',true);
 shop_a:=public.create_barbershop('Provisioning shop A','provision-'||a,null,null);
 if not (select shop_enabled from public.barbershops where id=shop_a) then raise exception 'FAIL new shop store disabled'; end if;
 if (select count(*) from public.shop_products where barbershop_id=shop_a and is_active and requires_confirmation and not track_stock and catalog_verified_by=a and catalog_verification_mode='reference_online')<>catalog_count then raise exception 'FAIL automatic full catalog'; end if;
 if (select coalesce(sum(stock_on_hand),0) from public.shop_product_variants where barbershop_id=shop_a)<>0 or exists(select 1 from public.inventory_movements where barbershop_id=shop_a) then raise exception 'FAIL invented physical stock'; end if;
 select count(*) into before_audit from public.shop_catalog_audit_events where barbershop_id=shop_a;
 r:=public.install_shop_reference_catalog(shop_a);
 if (r->>'created')::int<>0 or (r->>'already_present')::int<>catalog_count or (select count(*) from public.shop_catalog_audit_events where barbershop_id=shop_a)<>before_audit then raise exception 'FAIL retry duplicated catalog/audit'; end if;

 insert into public.services(barbershop_id,name,price_cents,duration_min,is_active) values(shop_a,'Provisioning booking service',12000,30,true) returning id into svc;
 insert into public.barbers(barbershop_id,display_name,is_active) values(shop_a,'Provisioning barber',true) returning id into barber;
 insert into public.barber_services(barber_id,service_id) values(barber,svc);
 select d.day into day from public.get_available_days('provision-'||a,svc,null,(now() at time zone 'Africa/Maputo')::date+2,(now() at time zone 'Africa/Maputo')::date+10) d where d.is_open and d.slots_count>0 order by d.day limit 1;
 select slot_start into slot from public.get_available_slots('provision-'||a,svc,null,day) order by slot_start limit 1;
 select pv.id,pv.price_minor into v,price from public.shop_product_variants pv join public.shop_products p on p.id=pv.product_id and p.barbershop_id=pv.barbershop_id where pv.barbershop_id=shop_a and p.product_kind='both' and p.is_active limit 1;
 items:=jsonb_build_array(jsonb_build_object('variant_id',v,'qty',2,'options','[]'::jsonb,'fulfilment_mode','consume_here'));
 select * into booking from public.book_appointment_with_shop_order_idempotent(key,'provision-'||a,svc,null,null,slot,'Reference booking fixture','840000099',null,items,repeat('a',64));
 select * into retry from public.book_appointment_with_shop_order_idempotent(key,'provision-'||a,svc,null,null,slot,'Reference booking fixture','840000099',null,items,repeat('a',64));
 if booking.shop_order_status<>'needs_confirmation' or booking.shop_subtotal_minor<>price*2 or retry.appointment_id<>booking.appointment_id then raise exception 'FAIL confirmation request, canonical price or retry'; end if;
 if not exists(select 1 from public.appointment_product_orders where appointment_id=booking.appointment_id and barbershop_id=shop_a and status='needs_confirmation') or exists(select 1 from public.inventory_reservations where barbershop_id=shop_a) then raise exception 'FAIL persisted confirmation or invented reservation'; end if;
 if booking.needs_payment or booking.deposit_cents<>0 then raise exception 'FAIL new booking requires disabled payment'; end if;
 select id into p from public.shop_products where barbershop_id=shop_a limit 1;
 select id into v from public.shop_product_variants where product_id=p;
 update public.shop_product_variants set price_minor=price_minor+100 where id=v returning price_minor into price;
 perform public.install_shop_reference_catalog(shop_a);
 if (select price_minor from public.shop_product_variants where id=v)<>price or (select is_active from public.shop_products where id=p) then raise exception 'FAIL reimport overwrites merchant edit or republishes'; end if;
 perform set_config('request.jwt.claim.sub',b::text,true);
 rejected:=false;
 begin perform public.install_shop_reference_catalog(shop_a); exception when insufficient_privilege then rejected:=sqlerrm='SHOP_CATALOG_FORBIDDEN'; end;
 if not rejected then raise exception 'FAIL cross-tenant install'; end if;
 shop_b:=public.create_barbershop('Provisioning shop B','provision-'||b,null,null);
 if (select count(*) from public.shop_products where barbershop_id=shop_b and is_active)<>catalog_count then raise exception 'FAIL second future shop'; end if;
 if exists(select 1 from public.shop_products pa join public.shop_products pb on pa.id=pb.id where pa.barbershop_id=shop_a and pb.barbershop_id=shop_b) then raise exception 'FAIL tenant data reused'; end if;
 update public.profiles set is_platform_admin=true where id=b;
 insert into public.barbershops(name,slug,status) values('Reference platform-admin fixture','reference-admin-'||gen_random_uuid(),'trial') returning id into orphan_shop;
 r:=public.install_shop_reference_catalog(orphan_shop);
 if (r->>'published')::int<>catalog_count or exists(select 1 from public.shop_products where barbershop_id=orphan_shop and catalog_verified_by is distinct from b) then raise exception 'FAIL actual admin actor for ownerless existing shop'; end if;
 update public.profiles set password_change_required=true where id=b;
 rejected:=false;
 begin perform public.install_shop_reference_catalog(orphan_shop); exception when insufficient_privilege then rejected:=sqlerrm='SHOP_CATALOG_FORBIDDEN'; end;
 if not rejected then raise exception 'FAIL password rotation bypass'; end if;
 perform set_config('request.jwt.claim.sub','',true);
 rejected:=false;
 begin perform public.install_shop_reference_catalog(shop_a); exception when insufficient_privilege then rejected:=sqlerrm='SHOP_CATALOG_FORBIDDEN'; end;
 perform set_config('request.jwt.claim.role','service_role',true);
 insert into public.barbershops(name,slug,status) values('System reference fixture','reference-system-'||gen_random_uuid(),'trial') returning id into system_shop;
 r:=public.install_shop_reference_catalog(system_shop);
 if (r->>'published')::int<>catalog_count or exists(select 1 from public.shop_products where barbershop_id=system_shop and (catalog_verified_by is not null or image_authorized_by is not null or catalog_verification_mode<>'reference_online')) then raise exception 'FAIL system import invents human actor or fails publication'; end if;
 if not rejected or has_function_privilege('anon','public.install_shop_reference_catalog(uuid)','execute') or has_table_privilege('authenticated','private.shop_catalog_references','select') then raise exception 'FAIL anonymous/private catalog boundary'; end if;
 raise notice 'PASS reference catalog: automatic current create flow, 23 real products, zero invented stock, explicit confirmation, actual actor, retry audit stability, merchant edit preservation, tenant isolation and private reference boundary.';
end;
$test$;
rollback;
